#include <array>
#include <vector>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <new>
#include <stdexcept>
namespace{bool tracking=false;uint64_t allocations=0;}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
using namespace ks;
struct Resolver{StateFieldCoordinator::Handler field(uint8_t c,uint32_t p){constexpr unsigned a[]{0x4f4a,0x4f06,0x51d8,0x51f4,0x5252,0x4f22,0x51fe,0x4f0c,0xb554};if(c>=9||p!=a[c])throw std::logic_error("Unsupported encoder field binding");return StateFieldCoordinator::Handler(c);}bool schema(uint8_t c,uint32_t p){switch(c){case 0:return p==0x4f4a;case 2:return p==0x51d8;case 3:return p==0x51f4;case 4:return p==0x5252;case 6:return p==0x51fe;default:return false;}}StatePackFieldsTask::Kind operator()(uint32_t p){constexpr unsigned a[]{0x68b0,0x68de,0x6922,0x6944,0x6970,0x69a6};for(unsigned n=0;n<6;++n)if((p&0xffffff)==a[n])return StatePackFieldsTask::Kind(n);throw std::logic_error("Unsupported encoder packing binding");}};
int main(){try{using T=ks::NativePedalControlService;using K=T::Kind;std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;Resolver resolver;
for(unsigned kind=0;kind<3;++kind)for(unsigned value=0;value<256;++value)for(unsigned controller:{3u,6u,64u,98u,122u}){if(kind==1&&controller!=64)continue;std::fill(m.begin()+0xb8e8,m.begin()+0x30000,uint8_t(0));const auto wide=[&](unsigned a,uint32_t v){for(unsigned n=0;n<4;++n)m[a+n]=uint8_t(v>>(24-8*n));};wide(0x167bc,0x18000);wide(0x167c0,0x19000);m[0x17526]=2;wide(0x174ae + 40,0x18000);m[0x174a6]=0;m[0x160d2+668+309]=16;m[0x160d2+668+332]=uint8_t(value);m[0x167ba]=0;m[0x167bb]=0;m[0x16798]=2;m[0x167d4]=2;m[0x1679a]=0;m[0x158f2]=4;m[0x1678d]=99;for(unsigned i=0;i<256;++i){m[71842+i]=uint8_t(i%128);m[71586+i]=uint8_t(i%4==0?126:0);m[0x18000+i]=uint8_t(i%128);}for(unsigned d=0;d<4;++d){wide(72134+4*d,0x12000+256*d);const unsigned desc=0x12000+256*d;m[desc]=d;m[desc+1]=64;m[desc+2]=3;m[desc+3]=0;for(unsigned i=4;i<256;i+=2){m[desc+i]=uint8_t(i%8);m[desc+i+1]=uint8_t(i/2);}}
unsigned count=0;int previous=-1;tracking=true;{T t(K(kind),{uint8_t(controller),uint8_t(value),2,0});while(!t.complete()){struct Unowned{};check(!t.task<Unowned>(),"Unknown pedal task query");const auto cost=t.nextClocks(previous);check(cost>0,"Pedal pure stalled");std::array<unsigned char,sizeof(T)>saved{};std::memcpy(saved.data(),&t,sizeof(T));unsigned callbacks=0;check(t.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},resolver,previous)==0&&!callbacks&&!std::memcmp(saved.data(),&t,sizeof(T)),"Pedal budget changed object");++rejects;const auto read=[&](uint32_t a,unsigned dt){check(a<(1u<<24)&&dt<=cost,"Pedal pure read bound");++reads;return a==0x400004||a==0x600004?uint8_t(255):m[a];};const auto write=[&](uint32_t a,uint8_t v,unsigned dt){check(a<(1u<<24)&&dt<=cost&&!(a>=0xfff000&&a<0xfffc00),"Pedal pure write bound");++writes;m[a]=v;previous=a<0x400000?int(a):-1;};check(t.advanceBefore(cost,read,write,resolver,previous)==cost,"Pedal pure admission");if(t.effect().write)previous=-1;check(++count<1000000,"Pedal pure did not complete");++phases;}
const auto&s=t.summary();if(!s.parameter){const unsigned base=0x160d2+668;check(m[base+309]==(value<64?0:16)&&m[base+310]==m[base+309],"Pedal scalar sustain oracle");}else if(controller==98)check(m[0x160d2+668+332]==value,"Selector scalar oracle");components|=t.components();}tracking=false;++graphs;}
check(components==31&&!allocations,"Pedal pure coverage/heap");std::cout<<"PASS Pure NativePedalControl graphs="<<graphs<<" phases="<<phases<<" whole_object_budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" sizeof="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;
}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
